CREATE COLUMN TABLE "TEST_AP"."OALT" ("Code" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(254), "Type" NVARCHAR(1) DEFAULT 'U', "Priority" NVARCHAR(1) DEFAULT '1', "Active" NVARCHAR(1) DEFAULT 'N', "NumOfParam" INTEGER CS_INT, "ParamData" NCLOB MEMORY THRESHOLD 1000, "Params" NCLOB MEMORY THRESHOLD 1000, "NumOfDocs" INTEGER CS_INT, "DocsData" NCLOB MEMORY THRESHOLD 1000, "Docs" NCLOB MEMORY THRESHOLD 1000, "UserText" NCLOB MEMORY THRESHOLD 1000, "QueryId" INTEGER CS_INT, "FrqncyType" NVARCHAR(1) DEFAULT 'H', "FrqncyIntr" INTEGER CS_INT DEFAULT 1, "ExecDaY" SMALLINT CS_INT DEFAULT 1, "ExecTime" INTEGER CS_INT DEFAULT 800, "LastDate" LONGDATE CS_LONGDATE, "LastTIME" SMALLINT CS_INT, "NextDate" LONGDATE CS_LONGDATE, "NextTime" SMALLINT CS_INT, "UserSign" SMALLINT CS_INT, "History" NVARCHAR(1) DEFAULT 'N', "QCategory" INTEGER CS_INT, PRIMARY KEY ("Code")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE INDEX "OALT_ACTIVE" ON "TEST_AP"."OALT" ( "Active" ASC );
CREATE INDEX "OALT_NAME" ON "TEST_AP"."OALT" ( "Name" ASC )